package com.trampolim.api.observatory;
import java.util.*;import java.time.*;
import com.trampolim.api.geography.TerritorialCatalog;import com.trampolim.api.radar.RadarBridge;import com.trampolim.api.company.CompanyRadarController;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class EmploymentObservatory extends SnapshotBatch {
 private final TerritorialCatalog geo;private final RadarBridge bridge;private final java.util.concurrent.Semaphore slots=new java.util.concurrent.Semaphore(4);private final com.trampolim.api.security.BoundedRateLimiter limiter=new com.trampolim.api.security.BoundedRateLimiter();
 @Value("${career.observatory-capture-enabled:true}")private boolean enabled;
 public EmploymentObservatory(@Qualifier("empresasJdbcTemplate")JdbcTemplate db,@Qualifier("empresasTransactionManager")PlatformTransactionManager manager,TerritorialCatalog geo,RadarBridge bridge){super(db,manager);this.geo=geo;this.bridge=bridge;}
 @Scheduled(initialDelayString="${observatory.v2.refresh-ms:900000}",fixedDelayString="${observatory.v2.refresh-ms:900000}")public void scheduled(){if(enabled)enqueue();}
 protected void build(UUID id,LocalDate from,Instant observed){var cities=new ArrayList<TerritorialCatalog.Municipality>();for(String code:db.queryForList("SELECT DISTINCT municipality_code FROM company_listings WHERE municipality_code IS NOT NULL",String.class))try{cities.add(geo.municipality(code));}catch(ResponseStatusException invalid){/* Unknown codes remain an explicit quality limitation. */}db.batchUpdate("INSERT INTO observatory_municipalities(code,name,state) VALUES (?,?,?) ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,state=EXCLUDED.state WHERE observatory_municipalities.name<>EXCLUDED.name OR observatory_municipalities.state<>EXCLUDED.state",cities,500,(ps,c)->{ps.setString(1,c.code());ps.setString(2,c.name());ps.setString(3,c.state());});
 String state="COALESCE(g.state,CASE WHEN UPPER(TRIM(c.state)) IN ('"+String.join("','",geo.states())+"') THEN UPPER(TRIM(c.state)) ELSE '' END)";
 String base="WITH base AS MATERIALIZED (SELECT l.id,c.id AS company_id,COALESCE(g.code,'') AS municipality,"+state+" AS state,COALESCE(NULLIF(TRIM(l.area),''),'Não informada') AS area,p.published_at,("+CompanyRadarController.PUBLIC_JOB_CONDITION+") AS active FROM company_listings l JOIN companies c ON c.id=l.company_id LEFT JOIN career_listing_publications p ON p.listing_id=l.id LEFT JOIN observatory_municipalities g ON g.code=l.municipality_code WHERE l.kind='job' AND c.verification_status='APPROVED' AND (l.is_internship=FALSE OR l.payment_status='PAID')), parts AS (SELECT date_trunc('month',published_at AT TIME ZONE 'America/Sao_Paulo')::date AS month,municipality,state,area,1 AS published,0 AS active,0 AS untracked FROM base WHERE published_at>=(?::date::timestamp AT TIME ZONE 'America/Sao_Paulo') AND published_at<=? UNION ALL SELECT date_trunc('month',?::timestamptz AT TIME ZONE 'America/Sao_Paulo')::date,municipality,state,area,0,1,CASE WHEN published_at IS NULL THEN 1 ELSE 0 END FROM base WHERE active=TRUE) ";
 db.update(base+"INSERT INTO observatory_vacancy_cells(run_id,month,municipality_code,state,area,published,active,untracked_active) SELECT ?,month,municipality,state,area,sum(published),sum(active),sum(untracked) FROM parts GROUP BY month,municipality,state,area",from,java.sql.Timestamp.from(observed),java.sql.Timestamp.from(observed),id);
 db.update("INSERT INTO observatory_company_presence(run_id,month,municipality_code,state,company_id) SELECT DISTINCT ?,date_trunc('month',p.published_at AT TIME ZONE 'America/Sao_Paulo')::date,COALESCE(g.code,''),"+state+",c.id FROM career_listing_publications p JOIN company_listings l ON l.id=p.listing_id JOIN companies c ON c.id=l.company_id LEFT JOIN observatory_municipalities g ON g.code=l.municipality_code WHERE l.kind='job' AND c.verification_status='APPROVED' AND (l.is_internship=FALSE OR l.payment_status='PAID') AND p.published_at>=(?::date::timestamp AT TIME ZONE 'America/Sao_Paulo') AND p.published_at<=?",id,from,java.sql.Timestamp.from(observed));
 String people="WITH events AS (SELECT 'APPLICATIONS' AS metric,a.created_at AS at,"+state+" AS state,LOWER(TRIM(a.candidate_email)) AS person,c.id AS company FROM company_applications a JOIN company_listings l ON l.id=a.listing_id JOIN companies c ON c.id=l.company_id LEFT JOIN observatory_municipalities g ON g.code=l.municipality_code WHERE l.kind='job' AND c.verification_status='APPROVED' UNION ALL SELECT 'INTERVIEWS_REPORTED_HELD',o.interview_at,"+state+",LOWER(TRIM(a.candidate_email)),c.id FROM company_selection_outcomes o JOIN company_applications a ON a.id=o.application_id JOIN company_listings l ON l.id=a.listing_id JOIN companies c ON c.id=l.company_id LEFT JOIN observatory_municipalities g ON g.code=l.municipality_code WHERE o.interview_held=TRUE AND c.verification_status='APPROVED' AND l.kind='job' UNION ALL SELECT 'CONFIRMED_HIRES',o.candidate_confirmed_at,"+state+",LOWER(TRIM(a.candidate_email)),c.id FROM company_selection_outcomes o JOIN company_applications a ON a.id=o.application_id JOIN company_listings l ON l.id=a.listing_id JOIN companies c ON c.id=l.company_id LEFT JOIN observatory_municipalities g ON g.code=l.municipality_code WHERE o.candidate_confirmed_at IS NOT NULL AND o.hire_date IS NOT NULL AND o.public_metrics_consent=TRUE AND c.verification_status='APPROVED' AND l.kind='job') ";
 db.update(people+"INSERT INTO observatory_personal_cells(run_id,metric,month,state,value,contributors,organizations) SELECT ?,metric,date_trunc('month',at AT TIME ZONE 'America/Sao_Paulo')::date,state,count(*),count(DISTINCT person),count(DISTINCT company) FROM events WHERE at>=(?::date::timestamp AT TIME ZONE 'America/Sao_Paulo') AND at<=? AND person<>'' AND state<>'' GROUP BY metric,3,state",id,from,java.sql.Timestamp.from(observed));
 }
 private record Scope(String state,List<String> codes){}
 private Scope scope(String state,String region,String municipality){var codes=geo.selection(region,municipality);String uf=state;if(!uf.isEmpty()&&!geo.states().contains(uf))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Selecione UF válida.");if(codes.isEmpty()&&uf.isEmpty()){var reference=(TerritorialCatalog.Municipality)geo.settings().get("referenceMunicipality");uf=reference.state();}if(!uf.isEmpty()&&codes.stream().anyMatch(c->!geo.municipality(c).state().equals(state))) {if(!state.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"O território não pertence à UF selecionada.");}if(!codes.isEmpty()&&uf.isEmpty()){var states=codes.stream().map(c->geo.municipality(c).state()).distinct().toList();if(states.size()==1)uf=states.getFirst();}return new Scope(uf,codes);}
 private String filter(Scope s,List<Object> args){String sql=" AND (?='' OR state=?)";args.add(s.state());args.add(s.state());if(!s.codes().isEmpty()){sql+=" AND municipality_code IN ("+String.join(",",Collections.nCopies(s.codes().size(),"?"))+")";args.addAll(s.codes());}return sql;}
 private Map<String,Object> metadata(Map<String,Object> run,String from,String to,Scope s){var out=new LinkedHashMap<String,Object>();out.put("status",run.get("status"));out.put("metricsVersion",2);out.put("state",s.state());out.put("municipalityCodes",s.codes());out.put("fromMonth",from);out.put("toMonth",to);out.put("notice","Registros da Trampolim, não estatística oficial nem retrato de todo o mercado regional. Anúncios não equivalem à quantidade de postos ou contratações.");if(run.get("observed_at")!=null){out.put("observedAt",run.get("observed_at"));out.put("coverageFrom",run.get("coverage_from"));out.put("coverageThrough",run.get("coverage_through"));}return out;}
 public Map<String,Object> overview(String from,String to,String state,String region,String municipality,String caller,boolean administrative){period(from,to);var s=scope(state,region,municipality);if(!limiter.allow(caller,30,Duration.ofMinutes(1))||!slots.tryAcquire())throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Aguarde antes de consultar novos indicadores.");try{return read(()->{var run=current();var out=metadata(run,from,to,s);if(!run.get("status").equals("READY"))return out;if((month(from).atDay(1).isBefore(((java.sql.Date)run.get("coverage_from")).toLocalDate())||month(to).isAfter(YearMonth.from(((java.sql.Date)run.get("coverage_through")).toLocalDate())))){out.put("status","OUTSIDE_COVERAGE");return out;}var args=new ArrayList<Object>(List.of(run.get("id"),month(from).atDay(1),month(to).atDay(1)));String where=" WHERE run_id=? AND month>=? AND month<=?"+filter(s,args);var series=db.queryForList("SELECT month,sum(published) AS published_listings FROM observatory_vacancy_cells"+where+" GROUP BY month ORDER BY month",args.toArray());var byMonth=new HashMap<String,Long>();for(var r:series)byMonth.put(r.get("month").toString(),count(r,"published_listings"));var months=new ArrayList<Map<String,Object>>();for(YearMonth m=month(from);!m.isAfter(month(to));m=m.plusMonths(1))months.add(Map.of("month",m.toString(),"registeredPublications",byMonth.getOrDefault(m.atDay(1).toString(),0L)));out.put("publicationSeries",months);out.put("registeredPublications",months.stream().mapToLong(v->((Number)v.get("registeredPublications")).longValue()).sum());
 var stockArgs=new ArrayList<Object>(List.of(run.get("id")));String stock=" WHERE run_id=?"+filter(s,stockArgs);var stocks=db.queryForMap("SELECT COALESCE(sum(active),0) AS active_listings,COALESCE(sum(untracked_active),0) AS active_without_publication_marker,COALESCE(sum(active) FILTER(WHERE municipality_code=''),0) AS active_without_valid_municipality FROM observatory_vacancy_cells"+stock,stockArgs.toArray());out.put("stocksAtCapture",stocks);out.put("participatingCompanies",db.queryForObject("SELECT count(DISTINCT company_id) FROM observatory_company_presence"+where,Long.class,args.toArray()));out.put("publicationTimeBasis","Primeira marca de publicação registrada; não criação do anúncio. Estágios exigem pagamento válido na captura. Não reconstrói divulgação anterior à instrumentação.");out.put("geographicBasis","Município IBGE do anúncio. Sem código válido: apenas UF-base empresarial, identificada nas limitações de qualidade. Não usa endereço residencial.");
 if(!s.codes().isEmpty()){out.put("recruitment",Map.of("status","MUNICIPAL_DATA_NOT_DISCLOSED"));out.put("learning",Map.of("status","MUNICIPAL_DATA_UNAVAILABLE","reason","Consentimento educacional registra somente UF; não será inferido município."));}else{out.put("recruitment",personal(run.get("id"),from,to,s.state(),administrative));try{out.put("learning",bridge.convert(bridge.post("/integrations/career/observatory/v2/learning",new ObservatoryController.LearningQuery(from,to,s.state())),Map.class));}catch(ResponseStatusException e){out.put("learning",Map.of("status","UNAVAILABLE"));}}out.put("restrictedMetrics",administrative?"INCLUDED_WITH_SUPPRESSION":"Candidaturas e entrevistas são indicadores operacionais restritos à administração global; não incluídos nesta resposta pública.");return out;});}finally{slots.release();}}
 private Map<String,Object> personal(Object run,String from,String to,String state,boolean admin){if(state.isEmpty())return Map.of("status","SELECT_SINGLE_STATE");var metrics=admin?List.of("CONFIRMED_HIRES","APPLICATIONS","INTERVIEWS_REPORTED_HELD"):List.of("CONFIRMED_HIRES");var rows=db.queryForList("SELECT metric,month,value,contributors,organizations FROM observatory_personal_cells WHERE run_id=? AND state=? AND month>=? AND month<=?",run,state,month(from).atDay(1),month(to).atDay(1));var values=new HashMap<String,Map<String,Object>>();for(var r:rows)values.put(r.get("metric")+":"+r.get("month"),r);var items=new ArrayList<Map<String,Object>>();for(YearMonth m=month(from);!m.isAfter(month(to));m=m.plusMonths(1)){var item=new LinkedHashMap<String,Object>();item.put("month",m.toString());for(String metric:metrics){var r=values.get(metric+":"+m.atDay(1));item.put(metric,r==null?privateBand(0,0,0,true):privateBand(count(r,"value"),count(r,"contributors"),count(r,"organizations"),true));}items.add(item);}return Map.of("status","READY","items",items,"privacy","Meses fixos por UF; mínimo dez identificadores de candidatura distintos e três empresas, valores em faixas de dez, sem totais pessoais combinados.");}
 public Map<String,Object> distribution(String from,String to,String state,String region,String municipality,String dimension,int offset,int limit,String caller){period(from,to);if(!Set.of("municipality","area").contains(dimension)||offset<0||offset>10000||limit<1||limit>50)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Dimensão ou paginação inválida.");var s=scope(state,region,municipality);if(!limiter.allow(caller,30,Duration.ofMinutes(1))||!slots.tryAcquire())throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS);try{return read(()->{var run=current();var out=metadata(run,from,to,s);if(!run.get("status").equals("READY"))return out;if((month(from).atDay(1).isBefore(((java.sql.Date)run.get("coverage_from")).toLocalDate())||month(to).isAfter(YearMonth.from(((java.sql.Date)run.get("coverage_through")).toLocalDate())))){out.put("status","OUTSIDE_COVERAGE");return out;}var args=new ArrayList<Object>(List.of(run.get("id"),month(from).atDay(1),month(to).atDay(1)));String where=" WHERE run_id=? AND month>=? AND month<=?"+filter(s,args),column=dimension.equals("area")?"area":"municipality_code";args.add(limit+1);args.add(offset);var rows=db.queryForList("SELECT "+column+" AS category,sum(published) AS registered_publications FROM observatory_vacancy_cells"+where+" GROUP BY "+column+" HAVING sum(published)>0 ORDER BY registered_publications DESC,category LIMIT ? OFFSET ?",args.toArray());for(var row:rows)if(dimension.equals("municipality"))row.put("label",row.get("category").equals("")?"Município não informado ou código não reconhecido":geo.label(row.get("category")));out.put("dimension",dimension);out.put("items",rows.stream().limit(limit).toList());out.put("hasMore",rows.size()>limit);return out;});}finally{slots.release();}}
}
